// SDF for upright equilateral triangle centered at origin, parameterized by circumradius r. d<0 inside.
float sdEquilateralTriangle_Centered(float2 p, float r)
{
    float k = 1.7320508; // sqrt(3)
    p.x = abs(p.x) - r;
    p.y = p.y + r / k;
    if (p.x + k * p.y > 0.0)
