    float dist = sdRegularNGon(pr, 1.0, 5.0);

    // 5) Anti-aliased edge (fixed-width AA in SDF space)
    float edge = smoothstep(0.01, -0.01, dist);

    // Output with smooth alpha
    outColor = float4(Color.rgb * edge, edge);
}
