// Signed distance to an origin-centered regular N-gon with circumradius r
// Robust straight-edge implementation based on Inigo Quilez (2015)
float sdRegularNGon(float2 p, float r, float n)
{
    // Angle for one sector
    float an = 2.0 * PI / n;

    // Rotate so that one vertex is aligned with the x-axis
    float halfAn = an * 0.5;
    float ca = cos(halfAn);
    float sa = sin(halfAn);
    float2 rp = float2(ca * p.x - sa * p.y, sa * p.x + ca * p.y);

    // Convert to polar
    float ang = atan2(rp.y, rp.x);
    float len = length(rp);

    // Wrap angle into the first sector [-an/2, an/2]
    ang = fmod(ang + halfAn, an) - halfAn;

    // Edge normal in this sector
    float2 nrm = float2(cos(halfAn), sin(halfAn));

    // Project point onto the edge normal and subtract radius to get signed distance
    float d = dot(float2(cos(ang), sin(ang)) * len, nrm) - r;
    return d;
}

void FunctionName_float(float2 UV, float Size, float Rotation, float4 Color, out float4 outColor)
{
    // Center UV coordinates (0.5,0.5 is screen center)
    float2 centered = UV - 0.5;

    // Map to -1..1 for easier uniform sizing (assumes square-ish aspect)
    float2 p = centered * 2.0;

    // Apply overall size scaling (0.5 ~ half screen, etc.)
    float safeSize = max(Size, 1e-4);
    p /= safeSize;

    // Rotate sampling point by -Rotation so shape appears rotated by +Rotation
    float c = cos(-Rotation);
    float s = sin(-Rotation);
    float2 pr = float2(c * p.x - s * p.y, s * p.x + c * p.y);

    // Regular pentagon SDF (circumradius = 1 in this normalized space)
    float dist = sdRegularNGon(pr, 1.0, 5.0);

    // Anti-aliased edge: small band around the boundary
    float aa = 0.0025; // tune as needed
    float edge = smoothstep(aa, -aa, dist);

    // Output with smooth alpha
    outColor = float4(Color.rgb * edge, edge);
}
